import { describe, expect, test } from "bun:test";
import { existsSync } from "node:fs";
import { join } from "node:path";
import {
  accountBalanceAt,
  accountBalanceHistory,
  netWorth,
  notgroschenProjection,
  investProjection,
  topfBalances,
  trimLeadingZeroNav,
} from "./analysis";
import { buildCycles, categoryKind } from "./cycles";
import { loadFinance } from "./load";

// Frozen fictional snapshot (data/test-fixtures, generated by
// scripts/generate-demo.ts) — the live transactions.csv changes on every
// import, so all exact-value assertions run against this.
const FIXTURES = join(import.meta.dir, "../../data/test-fixtures");
const hasFixtures = existsSync(join(FIXTURES, "transactions.csv"));
if (!hasFixtures) {
  // biome-ignore lint/suspicious/noConsole: test-environment notice
  console.warn("finance.test: data/test-fixtures missing — skipped");
}
const ifFixtures = hasFixtures ? test : test.skip;

const { finance, transactions: txs } = hasFixtures
  ? await loadFinance(FIXTURES)
  : { finance: undefined, transactions: [] };
const { vor, cycles } = hasFixtures
  ? buildCycles(txs, { account: "privat", budgetStart: finance!.budgetStart })
  : { vor: undefined, cycles: [] };
const c1 = cycles.find((c) => c.key === "2026-08-25")!;
const c2 = cycles.find((c) => c.key === "2026-09-25")!;

describe("pay cycles (Privatkonto, from budgetStart)", () => {
  ifFixtures("boundaries, labels and ranges", () => {
    expect(cycles.map((c) => c.key)).toEqual(["2026-08-25", "2026-09-25"]);
    expect(c1.label).toBe("Aug 2026 · 25.08.–24.09.");
    expect(c2.label).toBe("Sep 2026 · 25.09.–laufend");
    expect(c2.open).toBe(true);
    expect(vor?.label.startsWith("Vor-Zyklus")).toBe(true);
  });

  ifFixtures("cycle 2026-08-25 category sums", () => {
    expect(c1.byCategory).toEqual({
      Lohn: 4800,
      Notgroschen: -1200,
      Steuern: -250,
      "ETF IBKR": -1000,
      Krankenkasse: -385.2,
      Miete: -1280,
      "ÖV/Mobilität": -263.2,
      "Essen/Alltag": -136.1,
      "Internet/Handy": -59.9,
      Spesen: 0,
      Ausgehen: -80.5,
      "Technik/Abos": -37.85,
      "Freizeit/Shopping": -87.4,
      Kleidung: -59.95,
      Familie: -60,
      Bargeld: -100,
    });
    expect(c1.livingSpend).toBe(2490.1);
    expect(c1.savingsRate).toBeCloseTo(0.4583, 4);
  });

  ifFixtures("open cycle 2026-09-25", () => {
    expect(c2.byCategory["Gym"]).toBe(-540);
    expect(c2.byCategory["Krankenkasse"]).toBe(-385.2);
    expect(c2.byCategory["Jahreskosten/Diverses"]).toBe(-335);
    expect(c2.byCategory["Technik/Abos"]).toBe(-149);
    expect(c2.byCategory["Reisen"]).toBe(-265.9);
    expect(c2.byCategory["Essen/Alltag"]).toBe(-94.25);
    expect(c2.livingSpend).toBe(3280.25);
    expect(c2.savingsRate).toBeCloseTo(0.4583, 4);
  });

  ifFixtures("Vor-Zyklus (privat rows before the first Lohn)", () => {
    expect(vor?.byCategory["Essen/Alltag"]).toBe(-42.6);
    expect(vor?.byCategory["Kleidung"]).toBe(-85);
    expect(vor?.byCategory["Bargeld"]).toBe(-100);
  });
});

describe("category kinds", () => {
  test("income / savings / reserve / pass-through / transfer / spending", () => {
    expect(categoryKind("Lohn")).toBe("income");
    expect(categoryKind("Zinsen")).toBe("income");
    expect(categoryKind("Rückerstattungen")).toBe("income");
    expect(categoryKind("Notgroschen")).toBe("savings");
    expect(categoryKind("Steuern")).toBe("reserve");
    expect(categoryKind("Spesen")).toBe("passThrough");
    expect(categoryKind("Bildung")).toBe("spending");
    expect(categoryKind("Übertrag")).toBe("transfer");
    expect(categoryKind("Familie")).toBe("transfer");
    expect(categoryKind("Unkategorisiert")).toBe("spending");
  });
});

describe("account balances (anchor at balancesAsOf)", () => {
  const asOf = finance?.balancesAsOf ?? "";
  const acc = (id: string) => finance!.accounts.find((a) => a.id === id)!;
  const rows = (id: string) => txs.filter((t) => t.account === id);

  ifFixtures("privat", () => {
    expect(accountBalanceAt(rows("privat"), acc("privat").balance, asOf, "2026-09-07")).toBe(1642.45);
    expect(accountBalanceAt(rows("privat"), acc("privat").balance, asOf, "2026-09-25")).toBe(5853.9);
    // Before the first row the balance is whatever the opening was — derived, not stored.
    expect(accountBalanceAt(rows("privat"), acc("privat").balance, asOf, "2026-08-17")).toBe(1500);
    expect(accountBalanceAt(rows("privat"), acc("privat").balance, asOf, "2026-10-10")).toBe(218.85);
  });

  ifFixtures("notgroschen", () => {
    expect(accountBalanceAt(rows("notgroschen"), acc("notgroschen").balance, asOf, "2025-12-31")).toBe(2006.8);
    expect(accountBalanceAt(rows("notgroschen"), acc("notgroschen").balance, asOf, "2026-10-10")).toBe(4406.8);
  });

  ifFixtures("steuern", () => {
    expect(accountBalanceAt(rows("steuern"), acc("steuern").balance, asOf, "2026-10-10")).toBe(500);
  });

  ifFixtures("history starts at the first transaction and ends at the anchor", () => {
    const ng = accountBalanceHistory(rows("notgroschen"), acc("notgroschen").balance, asOf);
    expect(ng[0].date).toBe("2025-11-15");
    expect(ng.at(-1)).toEqual({ date: "2026-09-26", balance: 4406.8 });
  });
});

describe("Töpfe (since budgetStart)", () => {
  const topfe = hasFixtures ? topfBalances(finance!, txs) : [];
  const by = (n: string) => topfe.find((t) => t.name === n)!;

  ifFixtures("balances and recovery dates", () => {
    expect(by("Gym").balance).toBe(-400);
    expect(by("Gym").recoveryDate).toBe("2027-03-25");
    expect(by("ÖV/Mobilität").balance).toBe(-64.6);
    expect(by("ÖV/Mobilität").recoveryDate).toBe("2026-10-25");
    expect(by("Reisen").balance).toBe(174.1);
    expect(by("Technik/Abos").balance).toBe(93.15);
    expect(by("Steuern").balance).toBe(500);
  });
});

describe("projections", () => {
  test("Notgroschen reaches target on 2027-04-25 with a 393.20 last payment", () => {
    const p = notgroschenProjection(4406.8, 12000, 1200);
    expect(p.reachedDate).toBe("2027-04-25");
    expect(p.lastPayment).toBe(393.2);
  });

  test("investment projection at r=0 equals contributions + start value", () => {
    const series = investProjection(3120, 1000, 2380);
    const last = series.at(-1)!;
    expect(last.date).toBe("2036-12-25");
    expect(last.r0).toBe(291720);
  });
});

describe("net worth", () => {
  ifFixtures("sums all accounts", () => {
    expect(netWorth(finance!)).toBe(8245.65);
  });
});

describe("trimLeadingZeroNav (IBKR NAV history view)", () => {
  test("drops the leading zero run, keeps the last zero day", () => {
    const h = [
      { date: "2025-10-09", nav: 0 },
      { date: "2026-08-27", nav: 0 },
      { date: "2026-08-28", nav: 850 },
      { date: "2026-10-09", nav: 1698.3 },
    ];
    expect(trimLeadingZeroNav(h)).toEqual([
      { date: "2026-08-27", nav: 0 },
      { date: "2026-08-28", nav: 850 },
      { date: "2026-10-09", nav: 1698.3 },
    ]);
  });

  test("no leading zeros → unchanged", () => {
    const h = [{ date: "2026-08-28", nav: 850 }];
    expect(trimLeadingZeroNav(h)).toBe(h);
  });

  test("all zeros → unchanged (nothing to show either way)", () => {
    const h = [
      { date: "2025-10-09", nav: 0 },
      { date: "2025-10-10", nav: 0 },
    ];
    expect(trimLeadingZeroNav(h)).toBe(h);
  });
});
